function deepestNesting(frames: number[][]): number {
  const f = [...frames].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const best = new Array(f.length).fill(1);
  let ans = 0;
  for (let i = 0; i < f.length; i++) {
    for (let j = 0; j < i; j++) {
      if (f[j][0] < f[i][0] && f[j][1] < f[i][1]) best[i] = Math.max(best[i], best[j] + 1);
    }
    ans = Math.max(ans, best[i]);
  }
  return ans;
}

