class Solution:
    def deepestNesting(self, frames: List[List[int]]) -> int:
        f = sorted(frames)
        best = [1] * len(f)
        for i in range(len(f)):
            for j in range(i):
                if f[j][0] < f[i][0] and f[j][1] < f[i][1]:
                    best[i] = max(best[i], best[j] + 1)
        return max(best)

