function deepestNesting(frames: number[][]): number {
  const f = [...frames].sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const tails: number[] = [];
  for (const [, h] of f) {
    let lo = 0, hi = tails.length; // first index with tails[idx] >= h
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (tails[mid] < h) lo = mid + 1; else hi = mid;
    }
    tails[lo] = h;
  }
  return tails.length;
}

